package com.mediconnect.office.application;
import java.util.*; import com.mediconnect.office.api.*; import com.mediconnect.office.domain.OfficeEntity; import com.mediconnect.office.infrastructure.*; import com.mediconnect.shared.exception.ResourceNotFoundException; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @PreAuthorize("hasRole('ADMIN')") public class OfficeService { private final OfficeRepository repository; private final OfficeMapper mapper; public OfficeService(OfficeRepository repository,OfficeMapper mapper){this.repository=repository;this.mapper=mapper;} @Transactional(readOnly=true) public List<OfficeResponse> list(){return repository.findAll().stream().map(mapper::toResponse).toList();} @Transactional public OfficeResponse create(OfficeRequest request){OfficeEntity entity=new OfficeEntity(request.name().trim(),request.address().trim(),request.roomNumber());entity.update(request.name().trim(),request.address().trim(),request.roomNumber(),request.active());return mapper.toResponse(repository.save(entity));} @Transactional public OfficeResponse update(UUID id,OfficeRequest request){OfficeEntity entity=repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Office not found."));entity.update(request.name().trim(),request.address().trim(),request.roomNumber(),request.active());return mapper.toResponse(entity);} @Transactional public void delete(UUID id){if(!repository.existsById(id))throw new ResourceNotFoundException("Office not found.");repository.deleteById(id);} }
